import {isSanityConfigured} from '@/lib/env'

type Params = Record<string, unknown>

/** Result type generated by `sanity typegen` for a query defined with `defineQuery`. */
export type QueryResult<Q extends string> = Q extends keyof SanityQueries ? SanityQueries[Q] : never

/**
 * Runs a typed GROQ query. Uses Sanity (live, tagged, revalidated on publish) when a project is
 * configured, otherwise the local seed. `stega` stays off except in draft mode.
 */
export async function sanityQuery<const Q extends string>(
  query: Q,
  params: Params = {},
  options: {tags?: string[]; stega?: boolean} = {},
): Promise<QueryResult<Q>> {
  if (isSanityConfigured) {
    const {sanityFetch} = await import('./live')
    const {data} = await sanityFetch({query, params, tags: options.tags, stega: options.stega ?? false})
    return data as QueryResult<Q>
  }
  const {evaluateFixture} = await import('./fixtures')
  return evaluateFixture<QueryResult<Q>>(query, params)
}
